swiftui.code:
// Motion — 감속 대응은 Core JdMotion 이 단일 진입점이다.
// duration 이 0 이면 시스템이 모션 축소를 요구한 것 — 애니메이션을 통째로 끈다.
withAnimation(JdMotion.duration(0.3) == 0 ? nil : .easeOut) { isOpen.toggle() }

uikit.code:
// UIKit — 같은 판정을 UIView 애니메이션에 적용
let d = JdMotion.duration(0.3)
if d == 0 { apply() } else { UIView.animate(withDuration: d) { apply() } }
